import { Component, inject, signal, OnInit, OnDestroy } from '@angular/core';
import { DOCUMENT } from '@angular/common';
import { Router, ActivatedRoute } from '@angular/router';
import { CommonModule, NgOptimizedImage } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators, AbstractControl, ValidationErrors } from '@angular/forms';
import { AuthService } from '../../services/auth.service';
import { ThemeService } from '../../services/theme.service';
import { InstitutionalBarComponent } from '../../components/institutional-bar/institutional-bar.component';
import { MainNavbarComponent } from '../../components/main-navbar/main-navbar.component';
import { FooterSectionComponent } from '../../components/footer-section/footer-section.component';
import { environment } from '../../../environments/environment';

type LoginView = 'login' | 'register' | 'forgot' | 'verify';

@Component({
  selector: 'app-login',
  imports: [
    CommonModule,
    ReactiveFormsModule,
    NgOptimizedImage,
    InstitutionalBarComponent,
    MainNavbarComponent,
    FooterSectionComponent
  ],
  templateUrl: './login.html',
  styleUrl: './login.scss',
})
export class LoginComponent implements OnInit, OnDestroy {
  private readonly themeService = inject(ThemeService);
  private readonly document = inject(DOCUMENT);
  private readonly fb = inject(FormBuilder);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);
  protected readonly authService = inject(AuthService);
  readonly currentView = signal<LoginView>('login');
  readonly isLoading = signal<boolean>(false);
  readonly errorMessage = signal<string | null>(null);
  readonly successMessage = signal<string | null>(null);
  llaveMxEnabled = environment.enableLlaveMx;

  ngOnInit(): void {
    this.document.documentElement.setAttribute('data-bs-theme', 'light');

    const llaveMxError = this.route.snapshot.queryParamMap.get('llave_mx_error');
    if (llaveMxError) {
      this.errorMessage.set(this.llaveMxErrorMessage(llaveMxError));
      return;
    }
    
    if (this.authService.pendingVerificationEmail()) {
      this.currentView.set('verify');
    }
  }

  ngOnDestroy(): void {
    this.themeService.refreshTheme();
  }

  loginForm: FormGroup;
  registerForm: FormGroup;
  forgotForm: FormGroup;
  verifyForm: FormGroup;
  showPassword = signal<boolean>(false);
  showRegisterPassword = signal<boolean>(false);

  constructor() {
    this.loginForm = this.fb.group({
      email: ['', [Validators.required, Validators.email]],
      password: ['', [Validators.required, Validators.minLength(8)]],
    });

    this.registerForm = this.fb.group({
      name: ['', [Validators.required, Validators.minLength(3)]],
      email: ['', [Validators.required, Validators.email]],
      password: ['', [Validators.required, Validators.minLength(8)]],
      confirmPassword: ['', [Validators.required]],
    }, { validators: this.passwordMatchValidator });

    this.forgotForm = this.fb.group({
      email: ['', [Validators.required, Validators.email]],
    });

    this.verifyForm = this.fb.group({
      code: ['', [Validators.required, Validators.pattern(/^\d{6}$/)]],
    });
  }

  private passwordMatchValidator(control: AbstractControl): ValidationErrors | null {
    const password = control.get('password');
    const confirmPassword = control.get('confirmPassword');
    
    if (password && confirmPassword && password.value !== confirmPassword.value) {
      confirmPassword.setErrors({ passwordMismatch: true });
      return { passwordMismatch: true };
    }
    
    return null;
  }

  setView(view: LoginView) {
    this.currentView.set(view);
    this.errorMessage.set(null);
    this.successMessage.set(null);
    this.showPassword.set(false);
    this.showRegisterPassword.set(false);
    this.loginForm.reset();
    this.registerForm.reset();
    this.forgotForm.reset();
    if (this.verifyForm) {
      this.verifyForm.reset();
    }
    if (view === 'login') {
      const pendingEmail = this.authService.pendingVerificationEmail();
      if (pendingEmail) {
        this.loginForm.patchValue({ email: pendingEmail });
        this.authService.pendingVerificationEmail.set(null);
      }
    }
  }

  togglePasswordVisibility(field: 'login' | 'register') {
    if (field === 'login') {
      this.showPassword.update((val) => !val);
    } else {
      this.showRegisterPassword.update((val) => !val);
    }
  }

  onLogin() {
    if (this.loginForm.invalid) return;

    this.isLoading.set(true);
    this.errorMessage.set(null);

    const { email, password } = this.loginForm.value;

    this.authService.login(email, password).subscribe({
      next: () => {
        this.isLoading.set(false);
        const user = this.authService.currentUser();
        this.router.navigate(
          user ? this.authService.defaultRouteFor(user.role) : ['/'],
        );
      },
      error: (err) => {
        this.isLoading.set(false);
        if (err.status === 403 && err.error?.requires_verification) {
          this.authService.pendingVerificationEmail.set(err.error.email || email);
          this.setView('verify');
        } else if (err.status === 401) {
          this.errorMessage.set('Las credenciales proporcionadas son incorrectas.');
        } else {
          this.errorMessage.set('Ocurrió un error al intentar iniciar sesión. Inténtalo de nuevo.');
        }
      },
    });
  }

  onRegister() {
    if (this.registerForm.invalid) return;

    this.isLoading.set(true);
    this.errorMessage.set(null);

    const { name, email, password, confirmPassword } = this.registerForm.value;

    this.authService.register(name, email, password, confirmPassword).subscribe({
      next: () => {
        this.isLoading.set(false);
        this.authService.pendingVerificationEmail.set(email);
        this.setView('verify');
      },
      error: (err) => {
        this.isLoading.set(false);
        if (err.status === 422 && err.error?.errors) {
          const errors = err.error.errors;
          const firstErrorKey = Object.keys(errors)[0];
          this.errorMessage.set(errors[firstErrorKey][0]);
        } else {
          this.errorMessage.set('Ocurrió un error al intentar registrar la cuenta. Inténtalo de nuevo.');
        }
      },
    });
  }

  onVerify() {
    if (this.verifyForm.invalid) return;

    this.isLoading.set(true);
    this.errorMessage.set(null);

    const { code } = this.verifyForm.value;
    const email = this.authService.pendingVerificationEmail() ?? '';

    this.authService.verifyEmail(email, code).subscribe({
      next: (res) => {
        this.isLoading.set(false);
        this.successMessage.set(res.message || 'Correo verificado correctamente. Ya puedes iniciar sesión.');
        setTimeout(() => {
          this.successMessage.set(null);
          this.setView('login');
        }, 3000);
      },
      error: (err) => {
        this.isLoading.set(false);
        if (err.status === 422 && err.error?.errors) {
          const errors = err.error.errors;
          const firstErrorKey = Object.keys(errors)[0];
          this.errorMessage.set(errors[firstErrorKey][0]);
        } else {
          this.errorMessage.set('Ocurrió un error al verificar el código. Inténtalo de nuevo.');
        }
      },
    });
  }

  onResendCode() {
    this.isLoading.set(true);
    this.errorMessage.set(null);

    const email = this.authService.pendingVerificationEmail() ?? '';

    this.authService.resendVerification(email).subscribe({
      next: (res) => {
        this.isLoading.set(false);
        this.successMessage.set(res.message || 'Hemos enviado un nuevo código.');
      },
      error: () => {
        this.isLoading.set(false);
        this.errorMessage.set('No se pudo reenviar el código. Inténtalo de nuevo.');
      },
    });
  }

  onForgot() {
    if (this.forgotForm.invalid) return;

    this.isLoading.set(true);
    this.errorMessage.set(null);
    this.successMessage.set(null);

    const { email } = this.forgotForm.value;

    this.authService.forgotPassword(email).subscribe({
      next: (res) => {
        this.isLoading.set(false);
        this.successMessage.set(res.message || 'Se ha enviado el código de verificación.');
        setTimeout(() => {
          this.successMessage.set(null);
          this.router.navigate(['/reset-password'], { queryParams: { email } });
        }, 1500);
      },
      error: (err) => {
        this.isLoading.set(false);
        if (err.status === 400 && err.error?.errors) {
          this.errorMessage.set('No pudimos encontrar una cuenta con esa dirección de correo.');
        } else {
          this.errorMessage.set('Ocurrió un error al procesar tu solicitud. Inténtalo de nuevo.');
        }
      },
    });
  }

  onLlaveMxLogin(): void {
    this.errorMessage.set(null);
    window.location.assign(this.authService.llaveMxRedirectUrl());
  }

  private llaveMxErrorMessage(code: string): string {
    if (code === 'state' || code === 'callback') {
      return 'Tu intento de inicio de sesión con Llave MX expiró. Intenta nuevamente.';
    }
    if (code === 'token') {
      return 'No pudimos completar tu inicio de sesión con Llave MX. Intenta nuevamente.';
    }
    return 'Ocurrió un error al iniciar sesión con Llave MX. Intenta nuevamente.';
  }
}
